package com.cinenest.pricing.internal;
import java.util.*;
import java.sql.Types;
import com.nimbusds.jose.util.JSONObjectUtils;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;
@Repository
class JdbcDraftRepository implements DraftRepository {
 private final JdbcClient jdbc;
 JdbcDraftRepository(JdbcClient jdbc){this.jdbc=jdbc;}
 private static final String SELECT="SELECT p.package_id,p.venue_id,p.code,d.* FROM cinenest_pricing.package p JOIN cinenest_pricing.package_draft d USING(package_id) ";
 public Optional<Map<String,Object>> find(UUID venue,UUID id,boolean writeLock){return jdbc.sql(SELECT+"WHERE p.venue_id=:v AND p.package_id=:id"+(writeLock?" FOR UPDATE OF p,d":" FOR SHARE OF p,d")).param("v",venue).param("id",id).query((rs,n)->{
  Map<String,Object> d=new LinkedHashMap<>();d.put("packageId",id);d.put("venueId",venue);d.put("code",rs.getString("code"));d.put("name",rs.getString("name"));d.put("description",rs.getString("description"));d.put("currency",rs.getString("currency"));d.put("revision",rs.getLong("revision"));
  d.put("basePriceMinor",Long.toString(rs.getLong("base_price_minor")));d.put("includedMinutes",rs.getInt("included_minutes"));d.put("minimumMinutes",rs.getInt("minimum_minutes"));d.put("maximumMinutes",rs.getInt("maximum_minutes"));d.put("extensionsEnabled",rs.getBoolean("extensions_enabled"));d.put("extensionStepMinutes",rs.getObject("extension_step_minutes"));d.put("extensionPriceMinor",rs.getObject("extension_price_minor")==null?null:Long.toString(rs.getLong("extension_price_minor")));
  d.put("includedGuests",rs.getInt("included_guests"));d.put("maximumGuests",rs.getInt("maximum_guests"));d.put("extraGuestPriceMinor",Long.toString(rs.getLong("extra_guest_price_minor")));d.put("venueWide",rs.getBoolean("venue_wide"));d.put("policyId",rs.getObject("policy_id",UUID.class));d.put("policyRevision",rs.getLong("policy_revision"));d.put("status","DRAFT");d.put("taxStatus","UNRESOLVED");return d;
 }).optional().map(d->{d.put("roomIds",jdbc.sql("SELECT room_id FROM cinenest_pricing.package_draft_room WHERE package_id=:id ORDER BY room_id").param("id",id).query(UUID.class).list());d.put("options",jdbc.sql("SELECT service_id,rate_version_id,inclusion_mode FROM cinenest_pricing.package_draft_option WHERE package_id=:id ORDER BY service_id").param("id",id).query((rs,n)->Map.<String,Object>of("serviceId",rs.getObject(1,UUID.class),"rateVersionId",rs.getObject(2,UUID.class),"mode",rs.getString(3))).list());return d;});}
 public Map<String,Object> list(UUID venue,String q,int page,int size){String where=" FROM cinenest_pricing.package p JOIN cinenest_pricing.package_draft d USING(package_id) WHERE p.venue_id=:v AND (position(lower(:q) in lower(d.name))>0 OR position(lower(:q) in lower(p.code))>0)";
  long total=jdbc.sql("SELECT count(*)"+where).param("v",venue).param("q",q).query(Long.class).single();
  var ids=jdbc.sql("SELECT p.package_id"+where+" ORDER BY p.code,p.package_id LIMIT :size OFFSET :offset").param("v",venue).param("q",q).param("size",size).param("offset",(long)page*size).query(UUID.class).list();
  return new LinkedHashMap<>(Map.of("items",ids.stream().map(id->find(venue,id,false).orElseThrow()).toList(),"total",total,"page",page,"size",size));
 }
 public List<Map<String,Object>> options(UUID venue){return jdbc.sql("SELECT s.service_id,s.code,s.label,s.required_facility_code,r.rate_version_id,r.revision,r.unit_price_minor FROM cinenest_pricing.service_definition s JOIN cinenest_pricing.service_rate_version r USING(service_id) WHERE s.venue_id=:v AND s.approved=TRUE ORDER BY s.code,r.revision FOR SHARE OF s,r").param("v",venue).query((rs,n)->Map.<String,Object>of("serviceId",rs.getObject(1,UUID.class),"code",rs.getString(2),"label",rs.getString(3),"requiredFacilityCode",rs.getString(4),"rateVersionId",rs.getObject(5,UUID.class),"revision",rs.getLong(6),"unitPriceMinor",Long.toString(rs.getLong(7)),"currency","LKR","pricingBasis","PER_SESSION")).list();}
 public void save(UUID venue,UUID id,Map<String,Object>d,boolean create){
  if(create)jdbc.sql("INSERT INTO cinenest_pricing.package(package_id,venue_id,code) VALUES(:id,:v,:code)").param("id",id).param("v",venue).param("code",d.get("code")).update();
  String values="name=:name,description=:description,currency=:currency,base_price_minor=:base,included_minutes=:included,minimum_minutes=:minimum,maximum_minutes=:maximum,extensions_enabled=:extensions,extension_step_minutes=:step,extension_price_minor=:extensionPrice,included_guests=:guests,maximum_guests=:maxGuests,extra_guest_price_minor=:guestPrice,venue_wide=:wide,policy_id=:policy,policy_revision=:policyRevision";
  String insert="INSERT INTO cinenest_pricing.package_draft(package_id,revision,name,description,currency,base_price_minor,included_minutes,minimum_minutes,maximum_minutes,extensions_enabled,extension_step_minutes,extension_price_minor,included_guests,maximum_guests,extra_guest_price_minor,venue_wide,policy_id,policy_revision) VALUES(:id,0,:name,:description,:currency,:base,:included,:minimum,:maximum,:extensions,:step,:extensionPrice,:guests,:maxGuests,:guestPrice,:wide,:policy,:policyRevision)";
  var s=jdbc.sql(create?insert:"UPDATE cinenest_pricing.package_draft SET "+values+",revision=revision+1,updated_at=clock_timestamp() WHERE package_id=:id AND revision=:expected");
  s.param("id",id).param("name",d.get("name")).param("description",d.get("description")).param("currency","LKR").param("base",DraftRules.minor(d.get("basePriceMinor"),true)).param("included",d.get("includedMinutes")).param("minimum",d.get("minimumMinutes")).param("maximum",d.get("maximumMinutes")).param("extensions",d.get("extensionsEnabled")).param("step",d.get("extensionStepMinutes"),Types.INTEGER).param("extensionPrice",d.get("extensionPriceMinor")==null?null:DraftRules.minor(d.get("extensionPriceMinor"),false),Types.BIGINT).param("guests",d.get("includedGuests")).param("maxGuests",d.get("maximumGuests")).param("guestPrice",DraftRules.minor(d.get("extraGuestPriceMinor"),false)).param("wide",d.get("venueWide")).param("policy",d.get("policyId")).param("policyRevision",d.get("policyRevision"));
  if(!create)s.param("expected",d.get("expectedRevision"));if(s.update()!=1)throw new DraftFailure(409,"Draft changed; reload and compare");
  if(!create)jdbc.sql("UPDATE cinenest_pricing.package SET code=:code WHERE package_id=:id AND venue_id=:v").param("code",d.get("code")).param("id",id).param("v",venue).update();
  jdbc.sql("DELETE FROM cinenest_pricing.package_draft_room WHERE package_id=:id").param("id",id).update();for(UUID room:DraftRules.roomIds(d))jdbc.sql("INSERT INTO cinenest_pricing.package_draft_room VALUES(:id,:room)").param("id",id).param("room",room).update();
  jdbc.sql("DELETE FROM cinenest_pricing.package_draft_option WHERE package_id=:id").param("id",id).update();for(var o:DraftRules.objects(d,"options"))jdbc.sql("INSERT INTO cinenest_pricing.package_draft_option VALUES(:id,:service,:rate,:mode)").param("id",id).param("service",DraftRules.id((String)o.get("serviceId"))).param("rate",DraftRules.id((String)o.get("rateVersionId"))).param("mode",o.get("mode")).update();
 }
 public void history(UUID actor,UUID id,Map<String,Object> snapshot,String reason){jdbc.sql("INSERT INTO cinenest_pricing.package_draft_revision(package_id,revision,snapshot,actor_id,reason) VALUES(:id,:revision,CAST(:snapshot AS jsonb),:actor,:reason)").param("id",id).param("revision",snapshot.get("revision")).param("snapshot",JSONObjectUtils.toJSONString(snapshot)).param("actor",actor).param("reason",reason).update();}
 public Map<String,Object> history(UUID venue,UUID id,int page,int size){var items= jdbc.sql("SELECT h.revision,h.snapshot::text,h.occurred_at FROM cinenest_pricing.package_draft_revision h JOIN cinenest_pricing.package p USING(package_id) WHERE p.venue_id=:v AND p.package_id=:id ORDER BY h.revision DESC LIMIT :size OFFSET :offset").param("v",venue).param("id",id).param("size",size).param("offset",(long)page*size).query((rs,n)->{try{return Map.<String,Object>of("revision",rs.getLong(1),"snapshot",JSONObjectUtils.parse(rs.getString(2)),"occurredAt",rs.getTimestamp(3).toInstant().toString());}catch(java.text.ParseException e){throw new IllegalStateException("Invalid stored draft snapshot",e);}}).list();long total=jdbc.sql("SELECT count(*) FROM cinenest_pricing.package_draft_revision h JOIN cinenest_pricing.package p USING(package_id) WHERE p.venue_id=:v AND p.package_id=:id").param("v",venue).param("id",id).query(Long.class).single();return Map.of("items",items,"total",total,"page",page,"size",size);}
 public void audit(UUID actor,UUID venue,UUID id,String action,boolean allowed,Long old,Long next,String reason){jdbc.sql("INSERT INTO cinenest_pricing.configuration_audit VALUES(:event,:actor,:v,:id,:action,:outcome,:old,:next,:reason,clock_timestamp(),:correlation)").param("event",UUID.randomUUID()).param("actor",actor,Types.OTHER).param("v",venue,Types.OTHER).param("id",id,Types.OTHER).param("action",action).param("outcome",allowed?"ALLOW":"DENY").param("old",old,Types.BIGINT).param("next",next,Types.BIGINT).param("reason",reason).param("correlation",UUID.randomUUID()).update();}
}
